from sympy import symbols, solve, simplify

t = symbols("t", real=True)
curves = {
    "line": (1 + t, 2 * t - 1),
    "parabola": (t - 1, t**2),
    "loop": (t**2, t**3 - 3 * t),
}

count = int(input())
for i in range(count):
    parts = input().split()
    x, y = curves[parts[0]]
    a, b = int(parts[1]), int(parts[2])
    hits = []
    for c in solve(x - a, t):
        if simplify(y.subs(t, c) - b) == 0:
            hits.append(c)
    if hits:
        print(f"Problem {i + 1}: ({a}, {b}) on the {parts[0]} at t = {hits}")
    else:
        print(f"Problem {i + 1}: ({a}, {b}) not on the curve")

