import math


def simpson(f, a, b, n):
    h = (b - a) / n
    total = f(a) + f(b)
    for i in range(1, n):
        if i % 2 == 1:
            total = total + 4 * f(a + i * h)
        else:
            total = total + 2 * f(a + i * h)
    return total * h / 3


def value(text):
    # "2pi" means 2π, "pi" means π, and anything else is a plain number
    if text.endswith("pi"):
        if text == "pi":
            return math.pi
        return float(text[:-2]) * math.pi
    return float(text)


rates = {
    "circle": (lambda t: -3 * math.sin(t), lambda t: 3 * math.cos(t)),
    "segment": (lambda t: 3, lambda t: 4),
    "power": (lambda t: 2 * t, lambda t: 3 * t**2),
    "ellipse": (lambda t: -2 * math.sin(t), lambda t: math.cos(t)),
    "double": (lambda t: -2 * math.sin(2 * t), lambda t: 2 * math.cos(2 * t)),
}

count = int(input())
for i in range(count):
    name, a_text, b_text = input().split()
    dx, dy = rates[name]
    a, b = value(a_text), value(b_text)
    speed = lambda t: math.sqrt(dx(t)**2 + dy(t)**2)
    L = simpson(speed, a, b, 100)
    print(f"Problem {i + 1}: {name} from {a_text} to {b_text}, length {L:.4f}")
